"""Generate everything derived from bundles.json.

A bundle is a named part of the skill set that installs with one name:

    npx skills add TerrenoLabs/terreno-skills --skill lifecycle

The skills CLI only matches exact skill names, so each bundle is itself a skill:
a router SKILL.md plus a copy of every member skill under references/. The same
definitions also drive the picker groups (.claude-plugin/marketplace.json), the
skills.sh groupings (skills.sh.json), and the bundle table in README.md.

The picker only groups when it can read the marketplace, and once it can, it also
finds the Claude plugin tree's copies of the same skills under their plugin names
(`1-grow` beside `terreno-1-grow`). Those copies are marked `metadata.internal` so
the skills CLI skips them; Claude Code ignores the flag.

    python3 .github/scripts/bundles.py          # regenerate
    python3 .github/scripts/bundles.py --check  # fail when anything is stale
"""
import json
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
SKILLS = ROOT / "skills"
GUIDE = "GUIDE.md"
BUNDLES_PLUGIN = "bundles"
README_START = "<!-- bundles:start (generated by .github/scripts/bundles.py) -->"
README_END = "<!-- bundles:end -->"
MAX_DESCRIPTION = 1024


def load_config():
    config = json.loads((ROOT / "bundles.json").read_text())
    return config["repo"], config["bundles"]


def split_frontmatter(text):
    match = re.match(r"^---\n(.*?)\n---\n?", text, re.S)
    if not match:
        raise ValueError("missing frontmatter")
    return match.group(1), text[match.end():]


def frontmatter_value(front, key):
    """Read one top-level scalar: plain, quoted, or a folded/literal block."""
    lines = front.split("\n")
    for index, line in enumerate(lines):
        match = re.match(rf"^{key}:\s*(.*)$", line)
        if not match:
            continue
        value = match.group(1).strip()
        if not re.fullmatch(r"[>|][+-]?", value):
            if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
                value = value[1:-1]
            return value
        block = []
        for follow in lines[index + 1:]:
            if follow.strip() and not follow.startswith((" ", "\t")):
                break
            block.append(follow.strip())
        return " ".join(part for part in block if part)
    return ""


def member_description(name):
    front, _ = split_frontmatter((SKILLS / name / "SKILL.md").read_text())
    return frontmatter_value(front, "description")


def router(repo, bundle):
    name, members = bundle["name"], bundle["skills"]
    rows = "\n".join(
        f"| `{member}` | [references/{member}/{GUIDE}](references/{member}/{GUIDE}) | "
        f"{member_description(member).replace('|', chr(92) + '|')} |"
        for member in members
    )
    return f"""---
name: {name}
description: {json.dumps(bundle["description"], ensure_ascii=False)}
---

<!-- GENERATED from bundles.json by .github/scripts/bundles.py. Do not edit here. -->

# Terreno {bundle["title"].lower()} bundle

{bundle["summary"]}

This skill bundles {len(members)} Terreno skills into one install. Each member is a
complete guide under `references/<skill>/{GUIDE}`, with its own references, scripts, and
agents beside it.

## How to use this bundle

1. Match the request to one row in the table below.
2. Read that guide in full before acting. Resolve the guide's relative links
   (`references/...`, `scripts/...`, `agents/...`) from the guide's own folder.
3. When a guide tells you to invoke or load another skill by name:
   - installed as its own skill: invoke it as usual;
   - listed in the table below: read its guide here and follow it instead;
   - neither: say which skill is missing and offer
     `npx skills add {repo} --skill <name>`.

## Guides

| Skill | Guide | Read when |
| --- | --- | --- |
{rows}

## Installing a different slice

Every member also installs alone
(`npx skills add {repo} --skill {members[0]}`), and `npx skills add {repo}` opens a
picker grouped by the same bundles.
"""


def guide(member):
    _, body = split_frontmatter((SKILLS / member / "SKILL.md").read_text())
    return (
        f"<!-- GENERATED copy of skills/{member}/SKILL.md. Do not edit here. -->\n\n"
        + body.lstrip("\n")
    )


def is_executable(path):
    return bool(path.stat().st_mode & 0o111)


def is_current(path, content, executable):
    return (
        path.is_file()
        and path.read_bytes() == content
        and is_executable(path) == executable
    )


def bundle_files(repo, bundle):
    """Map of path (relative to the bundle folder) to (bytes, is_executable)."""
    files = {"SKILL.md": (router(repo, bundle).encode(), False)}
    for member in bundle["skills"]:
        source = SKILLS / member
        for path in sorted(source.rglob("*")):
            if not path.is_file():
                continue
            relative = path.relative_to(source)
            if relative.as_posix() == "SKILL.md":
                files[f"references/{member}/{GUIDE}"] = (guide(member).encode(), False)
            else:
                files[f"references/{member}/{relative.as_posix()}"] = (
                    path.read_bytes(),
                    is_executable(path),
                )
    return files


def plugin_skill_copies():
    """SKILL.md files inside plugin trees the marketplace exposes to the skills CLI."""
    data = json.loads((ROOT / ".claude-plugin/marketplace.json").read_text())
    copies = []
    for plugin in data["plugins"]:
        source = plugin.get("source")
        if "skills" in plugin or not isinstance(source, str):
            continue
        copies.extend(sorted((ROOT / source).glob("skills/*/SKILL.md")))
    return copies


def mark_internal(text):
    """Flag a plugin-tree skill so `npx skills add` does not list it twice."""
    front, body = split_frontmatter(text)
    if re.search(r"^metadata:", front, re.M):
        if re.search(r"^[ \t]+internal:\s*true\s*$", front, re.M):
            return text
        front = re.sub(r"^metadata:[ \t]*$", "metadata:\n  internal: true", front, count=1, flags=re.M)
    else:
        front = f"{front}\nmetadata:\n  internal: true"
    return f"---\n{front}\n---\n{body}"


def marketplace(bundles):
    """Add one plugin per bundle so the skills picker groups by bundle.

    The picker reads groups from plugins that list their `skills`; plugins without
    that list (the full `terreno` plugin) are left exactly as they are.
    """
    path = ROOT / ".claude-plugin/marketplace.json"
    data = json.loads(path.read_text())
    kept = [plugin for plugin in data["plugins"] if "skills" not in plugin]
    generated = [
        {
            "name": BUNDLES_PLUGIN,
            "source": "./",
            "strict": False,
            "description": "One skill per bundle: "
            + ", ".join(bundle["name"] for bundle in bundles)
            + ". Each carries its member skills as references.",
            "skills": [f"./skills/{bundle['name']}" for bundle in bundles],
        }
    ]
    for bundle in bundles:
        generated.append(
            {
                "name": f"terreno-{bundle['name']}",
                "source": "./",
                "strict": False,
                "description": f"Subset of the terreno plugin. {bundle['summary']}",
                "skills": [f"./skills/{member}" for member in bundle["skills"]],
            }
        )
    data["plugins"] = kept + generated
    # Plugin sources are written out in full, so a prepended root would break them.
    data.get("metadata", {}).pop("pluginRoot", None)
    if not data.get("metadata"):
        data.pop("metadata", None)
    return json.dumps(data, indent=2, ensure_ascii=False) + "\n"


def skills_sh(bundles):
    path = ROOT / "skills.sh.json"
    data = json.loads(path.read_text())
    data["groupings"] = [
        {
            "description": "One install per part of Terreno. Each bundle carries its member skills as references.",
            "skills": [bundle["name"] for bundle in bundles],
            "title": "Bundles",
        }
    ] + [
        {"description": bundle["summary"], "skills": bundle["skills"], "title": bundle["title"]}
        for bundle in bundles
    ]
    return json.dumps(data, indent=2, ensure_ascii=False) + "\n"


def readme(repo, bundles):
    path = ROOT / "README.md"
    text = path.read_text()
    if README_START not in text or README_END not in text:
        raise ValueError("README.md is missing the bundles markers")
    rows = "\n".join(
        f"| `{bundle['name']}` | `npx skills add {repo} --skill {bundle['name']}` | "
        f"{len(bundle['skills'])} | {bundle['summary']} |"
        for bundle in bundles
    )
    table = f"| Bundle | Install | Skills | What you get |\n| --- | --- | --- | --- |\n{rows}"
    head, rest = text.split(README_START, 1)
    _, tail = rest.split(README_END, 1)
    return f"{head}{README_START}\n{table}\n{README_END}{tail}"


def validate(bundles):
    errors = []
    names = [bundle["name"] for bundle in bundles]
    seen = {}
    for bundle in bundles:
        if len(bundle["description"]) > MAX_DESCRIPTION:
            errors.append(f"{bundle['name']}: description is over {MAX_DESCRIPTION} characters")
        for member in bundle["skills"]:
            if member in names:
                errors.append(f"{bundle['name']}: {member} is a bundle, not a skill")
            elif not (SKILLS / member / "SKILL.md").is_file():
                errors.append(f"{bundle['name']}: skills/{member}/SKILL.md not found")
            if member in seen:
                errors.append(f"{member}: in both {seen[member]} and {bundle['name']}")
            seen[member] = bundle["name"]
    for path in sorted(SKILLS.iterdir()):
        if path.is_dir() and path.name not in names and path.name not in seen:
            errors.append(f"skills/{path.name}: not in any bundle (add it to bundles.json)")
    return errors


def expected(repo, bundles):
    """Every generated file, keyed by path relative to the repo root."""
    files = {
        ".claude-plugin/marketplace.json": (marketplace(bundles).encode(), False),
        "skills.sh.json": (skills_sh(bundles).encode(), False),
        "README.md": (readme(repo, bundles).encode(), False),
    }
    for path in plugin_skill_copies():
        files[path.relative_to(ROOT).as_posix()] = (mark_internal(path.read_text()).encode(), False)
    for bundle in bundles:
        for relative, entry in bundle_files(repo, bundle).items():
            files[f"skills/{bundle['name']}/{relative}"] = entry
    return files


def existing_bundle_files(bundles):
    found = set()
    for bundle in bundles:
        folder = SKILLS / bundle["name"]
        if folder.is_dir():
            found.update(
                path.relative_to(ROOT).as_posix() for path in folder.rglob("*") if path.is_file()
            )
    return found


def main():
    check = "--check" in sys.argv[1:]
    repo, bundles = load_config()
    errors = validate(bundles)
    if errors:
        print("\n".join(errors))
        return 1
    files = expected(repo, bundles)
    stale = sorted(
        path for path, (content, executable) in files.items()
        if not is_current(ROOT / path, content, executable)
    )
    orphans = sorted(existing_bundle_files(bundles) - set(files))
    if check:
        for path in stale:
            print(f"stale: {path}")
        for path in orphans:
            print(f"orphan: {path}")
        if stale or orphans:
            print("Run: python3 .github/scripts/bundles.py")
            return 1
        print(f"{len(bundles)} bundles up to date")
        return 0
    for path in orphans:
        (ROOT / path).unlink()
    for path in stale:
        target = ROOT / path
        target.parent.mkdir(parents=True, exist_ok=True)
        content, executable = files[path]
        target.write_bytes(content)
        target.chmod(0o755 if executable else 0o644)
    for bundle in bundles:
        for folder in sorted((SKILLS / bundle["name"]).rglob("*"), reverse=True):
            if folder.is_dir() and not any(folder.iterdir()):
                folder.rmdir()
    print(f"{len(bundles)} bundles: wrote {len(stale)} files, removed {len(orphans)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
